contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: send `amount` to c.play()
    // amount must be provided by the caller (this function is payable to allow funding this contract in tests)
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough balance to send the specified amount
        require(address(this).balance >= amount);

        // observe pre-call public values
        address bankBefore = c.bank(); if (__ESBMC_reverted()) return;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceCBefore = address(c).balance;

        // perform the state-changing call and record whether it reverted
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe post-call public values
        address bankAfter = c.bank(); if (__ESBMC_reverted()) return;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balanceCAfter = address(c).balance;

        // General rule to hold for all inputs:
        // - bank address must never change
        // - if the call succeeded and the caller sent the exact ticket price, then either
        //     (A) pot increased exactly by amount (no payout happened), or
        //     (B) pot became 0 (a payout happened) and the contract balance after is <= balanceBefore + amount
        //         (i.e., contract cannot have more than it received if it paid out). We express (B) by potAfter == 0 and balanceCAfter <= balanceCBefore + amount.
        // - if the call reverted or amount != ticket, we only require bank immutability.

        bool sentTicket = (amount == 10);
        bool success = (!reverted);

        bool caseA = (success && sentTicket && potAfter == potBefore + amount);
        bool caseB = (success && sentTicket && potAfter == 0 && balanceCAfter <= balanceCBefore + amount);

        assert(bankBefore == bankAfter && (!success || !sentTicket || (caseA || caseB)));
    }

    // allow contract to receive refunds when play() transfers to msg.sender
    receive() external payable {}
}

